from h import *
# ---------- POINT 7
a=Pt(7)
a.p("L'approche syndromique regroupe les signes en ensembles qui orientent vers un mécanisme. Cinq syndromes se rencontrent dans la maladie lithiasique biliaire, du plus bénin au plus grave. Ce sont le syndrome biliaire douloureux, le syndrome inflammatoire de la vésicule, le syndrome de cholestase, le syndrome septique biliaire et le syndrome péritonéal.")
a.h("7.1 Syndrome biliaire douloureux (colique biliaire)")
a.p("Le signe fonctionnel dominant est la douleur biliaire : épisodique, sévère, haute, de plus de 30 minutes, avec nausées et vomissements et irradiation dorsale.[[wee35ed-7]] Le mécanisme est l'élévation de la pression intraluminale lorsque la vésicule se contracte contre un canal cystique obstrué.[[wee35ed-8]] À l'examen, l'abdomen est souple et la température normale, car l'obstruction partielle et brève ne provoque pas d'inflammation durable.[[wf130fd-3]]",
 ("pression intraluminale","<div class=\"p\">La pression intraluminale est la pression de la bile contenue dans la vésicule. Elle monte lorsque la vésicule se contracte contre un orifice obstrué, ce qui déclenche la douleur de la colique biliaire.[[wee35ed-8]]</div>"),
 ("irradiation dorsale","<div class=\"p\">L'irradiation vers le dos fait partie des caractéristiques accompagnatrices décrites par les groupes de consensus pour la douleur biliaire vraie, avec le début nocturne, les nausées et les vomissements.[[wee35ed-7]]</div>"))
a.h("7.2 Syndrome inflammatoire de la vésicule (cholécystite aiguë)")
a.p("Les signes fonctionnels sont des douleurs de l'hypochondre droit ou de l'épigastre avec nausées et vomissements.[[wf130fd-6]] Les signes physiques sont le signe de Murphy et la sensibilité, la douleur ou la masse de l'hypochondre droit.[[wf130fd-6]] Le syndrome inflammatoire systémique associe fièvre, CRP élevée et leucocytes élevés.[[wf130fd-6]] Le mécanisme est l'inflammation de la paroi consécutive à la stase biliaire et à l'ischémie muqueuse.[[wf130fd-3]]",
 ("syndrome inflammatoire","<div class=\"p\">Le syndrome inflammatoire biologique associe une CRP élevée et une leucocytose, ce qui confirme la présence d'une réaction inflammatoire systémique. Aucun test sanguin ne permet à lui seul d'affirmer la cholécystite.[[wf130fd-6]]</div><div class=\"p\">La CRP présente un retard sur la phase aiguë, ce qui peut la laisser normale au début de la crise.[[w683c0b-8]]</div>"))
a.h("7.3 Syndrome de cholestase et obstruction cholédocienne")
a.p("Le signe fonctionnel est l'ictère avec urines foncées et selles décolorées en cas d'obstruction biliaire complète.[[w7b1cf5-2]] Les signes biologiques sont la perturbation des tests hépatiques, qui doit faire suspecter une migration de calcul dans la voie biliaire principale.[[w7b1cf5-2]] Le mécanisme est le blocage d'un calcul dans le cholédoque, observé pour environ 20 % des calculs migrés.[[w7b1cf5-5]]",
 ("tests hépatiques","<div class=\"p\">Les tests hépatiques comprennent les transaminases, la gamma-glutamyl-transférase, la phosphatase alcaline et la bilirubine directe et indirecte. Des enzymes pancréatiques à plus de trois fois la norme suggèrent une pancréatite biliaire associée.[[w7b1cf5-5]]</div>"))
a.h("7.4 Syndrome septique biliaire (cholangite)")
a.p("La cholangite se présente classiquement, dans 50 à 70 % des cas, sous la forme de la triade de Charcot : fièvre, douleur abdominale et ictère.[[wf130fd-7]] La pentade de Reynolds comprend la triade de Charcot et des troubles de l'état de conscience.[[wf130fd-6]] Le mécanisme est l'obstruction des canaux biliaires avec pullulation bactérienne et translocation vers la circulation générale.[[wf130fd-6]]",
 ("pentade de Reynolds","<div class=\"p\">La pentade de Reynolds est la triade de Charcot associée à des troubles de l'état de conscience et à un état de choc. Elle est observée dans moins de 30 % des cas de cholangite.[[wf130fd-6]]</div>"))
a.h("7.5 Syndrome péritonéal (perforation)")
a.p("Les complications comprennent la perforation de la vésicule avec péritonite biliaire, l'abcès péricholécystique et la fistule duodénale.[[wf130fd-6]] Le signe fonctionnel est une douleur qui devient diffuse, et le signe physique est une défense ou une contracture abdominale. Chez le patient âgé, ces signes sont atténués.[[w683c0b-6]]")
a.t(["Syndrome","Signes fonctionnels","Signes physiques"],[
 ["7.1 Biliaire douloureux","Douleur épisodique de plus de 30 minutes, nausées, vomissements.[[wee35ed-7]]","Abdomen souple, apyrexie.[[wf130fd-3]]"],
 ["7.2 Inflammatoire vésiculaire","Douleur de l'hypochondre droit, nausées, vomissements.[[wf130fd-6]]","Murphy, masse sensible, fièvre.[[wf130fd-6]]"],
 ["7.3 Cholestase","Urines foncées, selles décolorées.[[w7b1cf5-2]]","Ictère.[[w7b1cf5-2]]"],
 ["7.4 Septique biliaire","Frissons, douleur.[[wf130fd-8]]","Fièvre, ictère, confusion, hypotension.[[wf130fd-6]]"],
 ["7.5 Péritonéal","Douleur diffuse.[[wf130fd-6]]","Défense, contracture, tachycardie."]])
a.save()
# ---------- POINT 8
b=Pt(8)
b.p("Le diagnostic positif de la cholécystite aiguë repose sur les critères de Tokyo, révisés en 2013 et conservés sans modification dans la version TG18.[[w48ae2e-12]] Ainsi, ils combinent un signe local, un signe systémique et une image caractéristique.")
b.h("8.a Critères diagnostiques de Tokyo (TG13/TG18)")
b.t(["Catégorie","Éléments"],[
 ["A. Signes locaux d'inflammation","A1 : signe de Murphy ; A2 : sensibilité, douleur ou masse de l'hypochondre droit.[[wf130fd-6]]"],
 ["B. Réponse inflammatoire systémique","B1 : fièvre ; B2 : CRP élevée ; B3 : leucocytose.[[wf130fd-6]]"],
 ["C. Imagerie","C1 : image caractéristique d'une cholécystite.[[wf130fd-6]]"],
 ["Diagnostic suspecté","Un élément de A et un élément de B.[[wf130fd-6]]"],
 ["Diagnostic confirmé","Un élément de A, un élément de B et un élément de C.[[wf130fd-6]]"]])
b.p("Dans l'étude de validation initiale de 2012, les critères de Tokyo avaient une sensibilité de 91,2 % et une spécificité de 96,9 %.[[w9a8a8f-24]] Les études ultérieures sont plus nuancées : l'exactitude globale des critères TG13 était de 60,3 % dans une série transversale, qui sur-diagnostiquait la cholécystite dans 62,5 % des vésicules normales.[[w9a8a8f-24]] La WSES recommande donc de ne jamais se fier à un seul signe clinique ou biologique.[[w9a8a8f-20]]",
 ("sensibilité et spécificité","<div class=\"p\">La sensibilité est la proportion de malades dont le test est positif. La spécificité est la proportion de non-malades dont le test est négatif, ce qui limite les faux positifs. Avec une sensibilité de 91,2 %, la plupart des malades sont détectés, et avec une spécificité de 96,9 %, peu de sujets sains sont étiquetés à tort.[[w9a8a8f-24]]</div>"))
b.h("8.b Critères radiologiques de la cholécystite aiguë")
b.t(["Élément visualisé à l'échographie ou au scanner","Seuil ou description"],[
 ["Épaississement de la paroi vésiculaire","Paroi de 5 mm ou plus.[[wf130fd-11]]"],
 ["Distension de la vésicule","Vésicule tendue.[[wf130fd-11]]"],
 ["Liquide périvésiculaire","Collection autour de la vésicule.[[wf130fd-11]]"],
 ["Signe de Murphy échographique","Paroi épaissie et feuilletée, douleur sous la sonde.[[wf130fd-11]]"],
 ["Calculs","Visibles dans la vésicule ou les voies biliaires.[[wf130fd-11]]"],
 ["Boue biliaire ou gaz","Présence dans la vésicule biliaire.[[wf130fd-11]]"]])
b.h("8.c Diagnostic positif des autres entités")
b.p("La colique biliaire se définit cliniquement par une douleur épisodique, constante et sévère de l'abdomen supérieur durant plus de 30 minutes.[[wee35ed-7]] Si des calculs sont visibles à l'imagerie, le diagnostic devient probable.[[wee35ed-7]] La NICE recommande de proposer un bilan hépatique et une échographie à toute personne chez qui l'on suspecte une maladie lithiasique.[[wa65cf9-2]]")
b.p("La cholangite se diagnostique selon les critères de Tokyo 2013 avec trois catégories.[[wf130fd-8]] La première est un signe d'inflammation, comme la fièvre ou les frissons. La deuxième est un signe de cholestase, ictère ou tests hépatiques perturbés, et la troisième est une imagerie montrant une dilatation des voies biliaires ou un obstacle visible.[[wf130fd-8]] Le diagnostic est suspecté avec un élément A et un élément B ou C, et confirmé avec un élément de chaque catégorie.[[wf130fd-8]]")
b.h("8.d Gravité de la cholécystite et de la cholangite")
b.p("La gradation de gravité TG13 de la cholécystite est associée à la mortalité à 30 jours, à la durée d'hospitalisation, au taux de conversion en chirurgie ouverte et aux coûts.[[w48ae2e-12]] Elle a été adoptée sans modification dans la version TG18.[[w48ae2e-12]] Les trois grades guident la conduite. Le grade I autorise la chirurgie précoce chez le patient peu comorbide, tandis que le grade II la permet avec un chirurgien expérimenté ou après drainage. Le grade III exige une prise en charge de la défaillance d'organe.[[we7ad29-12]]")
b.p("Pour la cholangite, le grade I n'est lié à aucun critère de gravité et répond au traitement médical initial.[[wf130fd-14]] Le grade II est associé à au moins deux des conditions suivantes : leucopénie ou leucocytose, fièvre élevée, âge supérieur à 75 ans, hyperbilirubinémie, hypo-albuminémie.[[wf130fd-14]] Le grade III correspond à une cholangite reliée à au moins une dysfonction d'organe : cardiovasculaire, respiratoire avec un rapport PaO2/FiO2 inférieur à 300, rénale, hépatique ou neurologique.[[wf130fd-16]]")
b.h("8.e Risque de calcul cholédocien")
b.t(["Risque","Critères (ASGE/SAGES 2010, repris par la Revue Médicale Suisse 2018)","Conduite"],[
 ["Faible, moins de 5 %","Tests hépatiques normaux, aucun critère intermédiaire ou élevé.[[w7b1cf5-11]]","Cholécystectomie sans autre investigation.[[w7b1cf5-2]]"],
 ["Intermédiaire, 5 à 50 %","Tests hépatiques perturbés avec bilirubine totale inférieure à 70 µmol/L, pancréatite biliaire ou âge supérieur à 55 ans.[[w7b1cf5-11]]","Écho-endoscopie, cholangio-IRM, ou cholécystectomie avec cholangiographie peropératoire.[[w7b1cf5-7]]"],
 ["Élevé, plus de 50 %","Calcul cholédocien visible, cholangite, bilirubine supérieure à 70 µmol/L, ou bilirubine de 30 à 70 µmol/L avec cholédoque dilaté de plus de 6 mm.[[w7b1cf5-12]]","Exploration et extraction de la voie biliaire principale.[[w7b1cf5-7]]"]])
b.p("La WSES propose une stratification plus prudente, car elle veut limiter les examens inutiles. Seule la visualisation d'un calcul cholédocien à l'échographie place le patient à haut risque, ce qui mène à une cholangiopancréatographie rétrograde endoscopique directe.[[w9a8a8f-51]] Une bilirubine supérieure à 4 mg/dL, ou un cholédoque dilaté avec une bilirubine de 1,8 à 4 mg/dL, définit un risque modéré.[[w9a8a8f-51]] Les deux classifications divergent, ce qui justifie de connaître celle que suit le centre.")
b.save()
# ---------- POINT 9
c=Pt(9)
c.p("Les examens complémentaires répondent à trois questions : confirmer la cholécystite, mesurer sa gravité et chercher un calcul dans la voie biliaire principale. Aucune imagerie n'est indispensable avant l'échographie, qui est l'examen de première intention.[[w9a8a8f-25]]")
c.h("9.a Gold standard")
c.p("La cholécystite aiguë ne possède pas de gold standard clinique unique, ce qui explique le recours à plusieurs critères. La scintigraphie hépatobiliaire (HIDA) a la sensibilité et la spécificité les plus élevées parmi les modalités d'imagerie, mais elle reste réservée à certains patients, selon l'expertise et la disponibilité locales.[[w9a8a8f-31]] Pour la lithiase de la voie biliaire principale, l'extraction endoscopique confirme le diagnostic de façon définitive.[[w7b1cf5-2]] Sur le plan histologique, l'examen de la vésicule retirée confirme l'inflammation, sans changer la conduite en urgence.")
c.h("9.b Première intention")
c.p("L'échographie abdominale est l'examen de première intention recommandé, en raison de son rapport coût-efficacité, de sa large disponibilité, de sa faible invasivité et de sa bonne précision pour la lithiase.[[w9a8a8f-25]] Elle est performante même lorsqu'elle est réalisée par un urgentiste non radiologue.[[wf130fd-10]] L'atelier des HUG indique que l'échographie a une sensibilité de 80 % et une spécificité de 95 % pour la cholécystite.[[w683c0b-8]] Sa sensibilité dépasse 90 % pour la lithiase.[[w683c0b-8]]",
 ("échographie biliaire","<div class=\"p\">L'échographie se fait à jeun, avec une sonde abdominale placée sous le rebord costal droit. On mesure l'épaisseur de la paroi vésiculaire, qui évoque la cholécystite à partir de 5 mm.[[wf130fd-11]] On recherche ensuite des calculs avec cône d'ombre, du liquide périvésiculaire et le signe de Murphy échographique, puis on mesure le calibre du cholédoque.[[wf130fd-11]]</div><div class=\"p\">Le signe de Murphy échographique a une sensibilité et une spécificité supérieures à 90 %.[[wf130fd-10]] L'échographie peut être négative en présence d'une cholélithiase, d'où l'importance de la clinique.[[w683c0b-8]]</div>"),
 ("sensibilité de l'échographie","<div class=\"p\">Les études d'imagerie sont hétérogènes, car la sensibilité de l'échographie va de 26 à 100 % et sa spécificité de 62 à 88,1 %.[[w9a8a8f-27]] Dans une étude, l'absence de calcul a servi à écarter la cholécystite chez les patients des urgences, avec une valeur prédictive négative élevée.[[w9a8a8f-28]]</div>"))
c.p("La biologie complète l'échographie, car elle mesure l'inflammation et l'atteinte biliaire. La numération formule sanguine et la CRP orientent vers l'inflammation, mais la CRP a un retard sur la phase aiguë.[[w683c0b-8]] Les tests hépatiques et la lipase cherchent une atteinte de la voie biliaire principale ou du pancréas. Le test de grossesse est systématique chez la femme en âge de procréer.[[w683c0b-8]] La NICE recommande un bilan hépatique et une échographie chez toute personne suspecte de maladie lithiasique.[[wa65cf9-2]]")
c.t(["Résultat","Signification","Conduite"],[
 ["CRP élevée, leucocytose","Réponse inflammatoire systémique.[[wf130fd-6]]","Évaluer la cholécystite ou la cholangite."],
 ["Paroi vésiculaire de 5 mm ou plus, liquide périvésiculaire","Image de cholécystite.[[wf130fd-11]]","Classer la gravité et planifier la chirurgie."],
 ["Tests hépatiques perturbés, bilirubine élevée","Calcul cholédocien possible.[[w7b1cf5-2]]","Stratifier le risque et explorer la voie biliaire.[[w9a8a8f-46]]"],
 ["Lipase supérieure à trois fois la norme","Pancréatite biliaire associée.[[w7b1cf5-5]]","Scanner si besoin d'évaluer l'étendue.[[w7b1cf5-5]]"],
 ["Calcul dans le cholédoque à l'échographie","Risque élevé de cholédocolithiase.[[w9a8a8f-43]]","Cholangiopancréatographie rétrograde endoscopique.[[w9a8a8f-54]]"],
 ["Cholédoque dilaté seul","Insuffisant pour affirmer la présence d'un calcul.[[w9a8a8f-43]]","Examens complémentaires de second niveau.[[w9a8a8f-43]]"]])
c.h("9.c Alternatives")
c.p("Chez la femme enceinte, les outils diagnostiques sont les mêmes que dans la population générale, avec les réserves sur la leucocytose et le signe de Murphy.[[w9a8a8f-75]] L'IRM est aussi précise que l'échographie pour la cholécystite et constitue une alternative lorsque l'échographie est non concluante, sans irradiation.[[w9a8a8f-31]] Le scanner a une précision diagnostique faible pour la cholécystite, mais il évalue les complications et les diagnostics différentiels, ce qui justifie de le réserver aux cas douteux.[[w9a8a8f-31]]",
 ("scanner abdominal","<div class=\"p\">La Revue Médicale Suisse retient l'échographie et le scanner avec produit de contraste intraveineux comme les deux examens d'imagerie de choix. L'échographie se fait en première intention, car sa sensibilité dépasse celle du scanner.[[wf130fd-10]]</div><div class=\"p\">La précision diagnostique du scanner est jugée faible pour la cholécystite dans les recommandations de la WSES.[[w9a8a8f-31]]</div>"))
c.h("9.d Deuxième intention : exploration de la voie biliaire principale")
c.p("Si l'échographie ne montre pas de calcul cholédocien, mais que le cholédoque est dilaté ou que les tests hépatiques sont perturbés, la NICE propose une cholangio-IRM. Elle propose une écho-endoscopie si la cholangio-IRM ne permet pas de conclure.[[wa65cf9-2]] L'ESGE recommande l'écho-endoscopie ou la cholangio-IRM en cas de suspicion clinique persistante avec échographie non concluante.[[wd7a757-7]] La cholangiopancréatographie rétrograde endoscopique est réservée à l'extraction, car elle expose à des complications.[[w9a8a8f-51]]")
c.p("Les patients à risque intermédiaire reçoivent l'une des quatre options suivantes selon l'expertise locale : cholangio-IRM préopératoire, écho-endoscopie préopératoire, cholangiographie peropératoire ou échographie laparoscopique.[[w9a8a8f-52]] Les patients à haut risque subissent une cholangiopancréatographie rétrograde préopératoire, une cholangiographie peropératoire ou une échographie laparoscopique.[[w9a8a8f-54]]",
 ("cholangiopancréatographie rétrograde endoscopique","<div class=\"p\">La cholangiopancréatographie rétrograde endoscopique (ERCP) est un geste endoscopique à visée thérapeutique : elle permet d'extraire un calcul de la voie biliaire principale.[[w7b1cf5-2]] Elle expose à des complications, c'est pourquoi on évite de la réaliser pour un bilan seul.[[w9a8a8f-51]]</div>"),
 ("écho-endoscopie","<div class=\"p\">L'évaluation de la voie biliaire principale se fait essentiellement par écho-endoscopie et cholangio-pancréatographie par résonance magnétique.[[w7b1cf5-2]]</div>"))
c.p("Pour la cholangite, l'ESGE fixe les délais de drainage biliaire selon la gravité TG18. Le drainage se fait au plus vite, dans les 12 heures, en cas de choc septique.[[wd7a757-8]] Il se fait dans les 48 à 72 heures pour une forme modérée, et de façon élective pour une forme légère.[[wd7a757-8]]")
c.p("Les valeurs de référence utilisent les unités du Système international : une bilirubine totale inférieure à 70 µmol/L définit le risque intermédiaire, et supérieure à 70 µmol/L le risque élevé de cholédocolithiase.[[w7b1cf5-12]]")
c.save()
